async () => { /* B0 bridge-1b left at least one judged Teague send with the two spoof tells (senderTrust, senderAuth), so the playerSent card has a record to replay */ const ms = window.mailState; if (!ms || !ms.mailboxes) return false;
  const recs = Object.values(ms.mailboxes).flatMap(b => (b && b.messages) || []).filter(r => r && r.folder === 'sent' && r.targetId === 'teague' && Array.isArray(r.tells));
  const spoof = recs.filter(r => r.tells.includes('senderTrust') && r.tells.includes('senderAuth'));
  return recs.length > 0 && spoof.length > 0; }

async () => { /* B1 the own_teague card is now replayed (not skipped): four messages, own_teague among them and marked as the player's own send */ const mg = window.MinigameFramework.currentMinigame; const s = mg.getTestState();
  const ids = s.triage.messages.map(m => m.id);
  const own = s.triage.messages.find(m => m.id === 'own_teague');
  return s.overlay.sceneType === 'inbox-triage' && s.triage.step === 'brief' && s.triage.setId === 'slice_inbox'
    && s.triage.total === 4 && ids.includes('own_teague') && s.triage.skipped.length === 0
    && !!own && own.playerSent === true; }

async () => { /* B2 opening own_teague: the header panel shows the account the mail was really sent from (SPF Fail, DKIM None, DMARC Fail), while the From line shows the spoofed Ledgerwell identity */ const mg = window.MinigameFramework.currentMinigame;
  const start = mg.container.querySelector('.tri-start'); if (!start) return false; start.click();
  const row = mg.container.querySelector('.mail-row[data-id="own_teague"]'); if (!row) return false; row.click();
  const panel = mg.container.querySelector('.tri-header-panel'); if (!panel) return false;
  const resultOf = (mech) => panel.querySelector('.tri-auth-row[data-mechanism="' + mech + '"]')?.dataset.result;
  const fromAddr = [...panel.querySelectorAll('.tri-header-fields dd')].map(d => d.textContent).join(' ');
  const s = mg.getTestState();
  return s.triage.selectedId === 'own_teague'
    && resultOf('spf') === 'fail' && resultOf('dkim') === 'none' && resultOf('dmarc') === 'fail'
    && /ledgerwell\.example/.test(fromAddr); }

async () => { /* B3 Report own_teague and name the two spoof tells that match the stored record */ const mg = window.MinigameFramework.currentMinigame;
  const report = mg.container.querySelector('.tri-verdict[data-verdict="report"]'); if (!report) return false; report.click();
  mg.container.querySelector('input[data-chip="senderTrust"]').click();
  mg.container.querySelector('input[data-chip="senderAuth"]').click();
  mg.container.querySelector('.tri-confirm').click();
  const s = mg.getTestState();
  return s.triage.answered === 1 && s.triage.messages.find(m => m.id === 'own_teague').verdict === 'report'; }

async () => { /* B4 answer the other three so the round can finish */ const mg = window.MinigameFramework.currentMinigame;
  const answer = (id, verdict, chips) => { const row = mg.container.querySelector('.mail-row[data-id="' + id + '"]'); if (!row) return false; row.click();
    const v = mg.container.querySelector('.tri-verdict[data-verdict="' + verdict + '"]'); if (!v) return false; v.click();
    chips.forEach(c => mg.container.querySelector('input[data-chip="' + c + '"]').click());
    mg.container.querySelector('.tri-confirm').click(); return true; };
  if (!answer('pay_today', 'report', ['senderTrust','linkCredible','urgencyCalibrated'])) return false;
  if (!answer('parking', 'trust', ['none'])) return false;
  if (!answer('laptop', 'trust', ['none'])) return false;
  const s = mg.getTestState();
  return s.triage.step === 'review' && s.triage.answered === 4; }

async () => { /* B5 the own_teague review card: the two spoof tells are caught, none missed, no false-flag line for a tell that was ticked; its verdict reads as a right call */ const mg = window.MinigameFramework.currentMinigame; const s = mg.getTestState();
  const card = s.triage.review.cards.find(c => c.id === 'own_teague'); if (!card) return false;
  const cardEl = mg.container.querySelector('.tri-review-card[data-message-id="own_teague"]'); if (!cardEl) return false;
  const verdict = cardEl.querySelector('.tri-card-verdict');
  return card.caught.slice().sort().join() === 'senderAuth,senderTrust' && card.missed.length === 0
    && card.falseClaims.length === 0
    && !!verdict && verdict.classList.contains('right'); }

async () => { /* B6 See result: a full score, because every message was answered right with the right flags */ const mg = window.MinigameFramework.currentMinigame;
  const next = mg.container.querySelector('.tri-next'); if (!next) return false; next.click();
  const s = mg.getTestState(); const r = s.triage.result;
  return s.triage.step === 'result' && !!r && r.percent === 100 && r.headline === 'Sharp'
    && r.phishCaught === 2 && r.phishTotal === 2 && r.falseAlarms === 0; }

async () => { /* B7 Finish completes normally and the task is recorded */ const t = window.__test; await new Promise(r => setTimeout(r, 400));
  const g = t.getState().globals;
  return !t.getState().activeMinigame && g.slice_triage_done === true && g.slice_triage_pass === true
    && t.getState().objectives.completedTasks.includes('triage_sorted'); }
